<template><view class="progress" :class="element?'element-'+element:''" role="progressbar" :aria-label="label" :aria-valuenow="percent" aria-valuemin="0" aria-valuemax="100"><view class="bar" :style="{width:percent+'%'}" /></view></template>
<script setup lang="ts">import {computed} from 'vue';import type {Element} from '../../../packages/pet_engine';const p=defineProps<{value:number;total:number;label:string;element?:Element}>();const percent=computed(()=>Math.min(100,Math.max(0,p.total ? p.value/p.total*100:0)))</script>
<style scoped>.progress{height:9px;background:var(--wp-element-soft,var(--wp-secondary));border-radius:var(--wp-radius-lg);overflow:hidden}.bar{height:100%;background:var(--wp-element-bright,var(--wp-primary));border-radius:inherit;transition:width var(--wp-motion-normal)}</style>
